CORE="    // GBClinical M2 — generic declarative clinical engine (M6.4)\n    const GBClinical=(()=>{\n      const own=(o,k)=>o!=null&&Object.hasOwn(o,k),copy=x=>JSON.parse(JSON.stringify(x));\n      const safe=k=>typeof k==='string'&&/^[A-Za-z][\\w-]*$/.test(k)&&!['constructor','prototype','__proto__'].includes(k);\n      function get(s,path){let v=s;for(const k of path.split('.')){if(!safe(k)||!own(v,k))return null;v=v[k];}return v;}\n      function expr(x,s,depth=0){if(depth>24)throw Error('Expressão profunda');if(x===null||['string','number','boolean'].includes(typeof x))return x;if(!Array.isArray(x))throw Error('Expressão inválida');const [op,...args]=x;if(op==='get')return get(s,args[0]);const a=()=>expr(args[0],s,depth+1),b=()=>expr(args[1],s,depth+1);switch(op){case 'and':return args.every(t=>expr(t,s,depth+1));case 'or':return args.some(t=>expr(t,s,depth+1));case 'not':return !a();case 'eq':return a()===b();case 'ne':return a()!==b();case 'lt':return typeof a()==='number'&&typeof b()==='number'&&a()<b();case 'gte':return typeof a()==='number'&&typeof b()==='number'&&a()>=b();case 'lte':return typeof a()==='number'&&typeof b()==='number'&&a()<=b();case 'add':return a()+b();case 'sub':return a()-b();case 'mul':return a()*b();case 'min':return Math.min(a(),b());case 'max':return Math.max(a(),b());case 'round':return Math.round(a());case 'concat':return args.map(t=>expr(t,s,depth+1)).join('');default:throw Error('Operador não permitido: '+op);}}\n      // Every decision/behavior rule is a bounded graph, interpreted by the shared M6.3 executor.\n      function select(group,s){if(!group||!Array.isArray(group.rules)||group.rules.length<1||group.rules.length>100)throw Error('Grupo de regras inválido');const input={selected:-1};const actions={};group.rules.forEach((r,i)=>{input['match'+i]=!!expr(r.when,s);actions['choose'+i]=[{field:'selected',op:'set',value:i}];});const result=GBModuleRuntime.run(group.flow,input,actions);const r=group.rules[result.state.selected];if(!r)throw Error('Nenhuma regra aplicável');return {rule:r,trace:result.trace};}\n      function setFields(state,fields,source){for(const [k,x] of Object.entries(fields||{})){if(!safe(k)||!own(state,k))throw Error('Campo não declarado: '+k);const v=expr(x,source);if(typeof v==='number'&&!Number.isFinite(v)||typeof v!==typeof state[k])throw Error('Tipo de estado inválido: '+k);state[k]=v;}}\n      function validate(m){if(!m||m.schema!=='gamebras.clinical/1'||!safe(m.id)||!Array.isArray(m.cases)||!m.cases.length||m.cases.length>100||!m.actions||!m.patients)throw Error('Módulo clínico inválido');const ids=new Set();for(const c of m.cases){if(!safe(c.id)||ids.has(c.id)||!c.state)throw Error('Caso inválido');ids.add(c.id);for(const [k,v] of Object.entries(c.state))if(!safe(k)||!['number','string','boolean'].includes(typeof v)||typeof v==='number'&&!Number.isFinite(v))throw Error('Variável inválida: '+k);}for(const id of Object.values(m.patients))if(!ids.has(id))throw Error('Paciente sem caso');for(const [id,a] of Object.entries(m.actions)){if(!safe(id)||!Number.isSafeInteger(a.minutes)||a.minutes<0||a.minutes>1440||!Array.isArray(a.rules))throw Error('Ação inválida: '+id);}return m;}\n      let active=null;\n      function use(m){active=m?validate(m):null;return active;}\n      class Patient{\n        constructor(id,m=active){validate(m);const c=m.cases.find(x=>x.id===id);if(!c)throw Error('Caso desconhecido');Object.defineProperty(this,'module',{value:m,enumerable:false});this.id=id;this.name=c.name;this.story=c.story;this.state=copy(c.state);this.elapsed=0;this.log=[];this.observed={};this.score=0;this.finished=false;this.outcome=null;this.awarded={};this.errors=[];this.feedback=m.initialFeedback||'Avalie antes de intervir.';}\n        context(){return {...this.state,elapsed:this.elapsed,observed:this.observed,finished:this.finished,outcome:this.outcome,story:this.story};}\n        advance(n){if(!Number.isSafeInteger(n)||n<0||n>10000000)throw Error('Tempo inválido');if(this.finished&&this.outcome!=='unsafe')return;for(let i=0;i<n;i++){this.elapsed++;const before=this.context();setFields(this.state,this.module.evolution,before);}}\n        act(id){if(this.finished)throw Error('Caso encerrado');if(!own(this.module.actions,id))throw Error('Ação inválida');const a=this.module.actions[id],before=this.context(),{rule:r,trace}=select(a,before);const state=copy(this.state),observed=copy(this.observed);setFields(state,r.set,before);for(const [key,fields] of Object.entries(r.observe||{})){if(!safe(key))throw Error('Observação inválida');observed[key]=Object.fromEntries(Object.entries(fields).map(([k,v])=>[k,expr(v,before)]));}let points=r.points||0;if(!Number.isFinite(points))throw Error('Pontuação inválida');const classification=r.classification||'neutral';if(points>0&&own(this.awarded,id))points=0;if(points>0)this.awarded[id]=true;const feedback=String(expr(r.message,before));this.state=state;this.observed=observed;this.score+=points;this.feedback=feedback;if(r.outcome){this.finished=true;this.outcome=r.outcome;}const record={minute:this.elapsed,action:id,feedback,points,classification,trace,outcome:this.outcome};this.log.push(record);if(this.log.length>2000)this.log.shift();if(classification==='error'){this.errors.push({...record,state:before});if(this.errors.length>2000)this.errors.shift();}return a.minutes;}\n        get behavior(){return select(this.module.behavior,this.context()).rule.value;}\n        get guidance(){return select(this.module.guidance,this.context()).rule.value;}\n        get exam(){return select(this.module.exam,this.context()).rule.value;}\n      }\n      function observations(p){return (p.module.observations||[]).map(o=>{const v=p.observed[o.id];return o.label+': '+(v?o.fields.map(f=>String(v[f.key])+(f.unit?' '+f.unit:'')).join(' · ')+' (min '+v.at+')':'não registrado');}).join('\\n');}\n      function sync(s){if(s.clinical){s.clinical.advance(s.minute-(s.clinicalAt??s.minute));s.clinicalAt=s.minute;}}\n      function render(e){const s=e.gbSimulation,p=s.clinical,box=document.getElementById('gb-clinical-body'),sel=document.getElementById('gb-clinical-select');if(!box)return;const m=e.mapData?.clinicalModule;const section=box.parentElement;section.hidden=!m;if(!m)return;if(sel.dataset.module!==m.id||sel.dataset.cases!==JSON.stringify(m.cases.map(c=>c.id))){sel.replaceChildren();for(const c of m.cases){const o=document.createElement('option');o.value=c.id;o.textContent=c.name;sel.append(o);}sel.dataset.module=m.id;sel.dataset.cases=JSON.stringify(m.cases.map(c=>c.id));}box.replaceChildren();const add=(tag,t)=>{const x=document.createElement(tag);x.textContent=t;box.append(x);return x;};if(!p){add('p','Escolha um caso clínico.');return;}add('h3',p.name);add('p',p.story);add('p','Tempo: '+p.elapsed+' min | Pontos: '+p.score);add('p',observations(p));add('p',p.feedback);if(!p.finished)for(const [id,a] of Object.entries(p.module.actions)){const b=add('button',a.label);b.type='button';b.onclick=()=>{try{const n=p.act(id);s.record('clínica',id+': '+p.feedback);s.advance(n,e.storyFlags);GBSimulation.refresh(e);}catch(err){add('p',err.message);}};}for(const r of p.log.slice(-12).reverse())add('p',r.minute+' min · '+p.module.actions[r.action].label+' · '+r.feedback);}\n      function init(e){const panel=document.getElementById('gb-sim-panel');if(!panel||document.getElementById('gb-clinical-body'))return;const section=document.createElement('section');section.style.cssText='display:grid;gap:6px;margin-top:12px;border-top:1px solid #64748b;padding-top:8px';const title=document.createElement('h3');title.textContent='Laboratório clínico (experimental)';section.append(title);const select=document.createElement('select');select.id='gb-clinical-select';section.append(select);const b=document.createElement('button');b.textContent='Iniciar caso clínico';b.type='button';b.onclick=()=>{const s=e.gbSimulation,m=e.mapData?.clinicalModule;if(!m)return;if(s.clinical&&!s.clinical.finished&&!confirm('Substituir caso em andamento?'))return;s.clinical=new Patient(select.value,m);s.clinicalAt=s.minute;s.record('clínica','Início: '+select.value);render(e);};section.append(b);const body=document.createElement('div');body.id='gb-clinical-body';body.style.cssText='display:grid;gap:6px;white-space:pre-line';section.append(body);panel.append(section);render(e);}\n      return {Patient,validate,use,get active(){return active;},get actions(){return active?.actions||{};},expr,select,observations,sync,render,init};\n    })();\n    // Generic encounter coordinator\n    const GBWard=(()=>{\n      function sync(s){for(const p of Object.values(s.ward||{})){p.advance(Math.max(0,s.minute-p.at));p.at=s.minute;}}\n      function start(s,m=GBClinical.active){if(!m)return null;if(!s.ward||s.moduleId!==m.id){s.moduleId=m.id;s.ward=Object.create(null);for(const [name,id] of Object.entries(m.patients)){const p=new GBClinical.Patient(id,m);p.at=s.minute;s.ward[name]=p;}}return s.ward;}\n      function act(e,p,id){const s=e.gbSimulation;sync(s);const a=p.module.actions[id];if(a.item&&!e.items.inventory.has(a.item))return 'Obtenha o recurso na mochila antes de realizar esta ação.';const n=p.act(id);const r=p.log.at(-1);if(r.classification==='error')s.record('erro clínico simulado',p.name+': '+p.feedback);s.record('clínica',p.name+' / '+id+' / '+p.feedback);s.advance(n,e.storyFlags);GBSimulation.refresh(e);return p.feedback;}\n      function review(ward){return Object.entries(ward||{}).map(([name,p])=>[name+' — '+(p.finished?p.outcome:'pendente')+' | '+p.score+' pontos',...p.log.map(r=>r.minute+' min · '+p.module.actions[r.action].label+' · '+r.classification+' · '+r.points+' · '+r.feedback),'Erros registrados: '+p.errors.length].join('\\n')).join('\\n\\n');}\n      function open(e,npc){const m=e.mapData?.clinicalModule;if(!m||!Object.hasOwn(m.patients,npc.name))return false;const s=e.gbSimulation,p=start(s,m)[npc.name];sync(s);clearTimeout(e._toastTimeout);e.activeDialogue=npc;e.audio.stopSpeech();const box=document.getElementById('dialogue-box'),choices=document.getElementById('dialogue-choices'),body=document.getElementById('dialogue-text');document.getElementById('dialogue-speaker').textContent=npc.name+' · prontuário';box.classList.remove('hidden');\n        function draw(message){choices.replaceChildren();body.textContent=[p.observed.history?.text||'Realize anamnese e exame.','Tempo: '+p.elapsed+' min | Pontos: '+p.score,GBClinical.observations(p),message||p.feedback,'Erros clínicos simulados: '+p.errors.length,p.finished?'Atendimento encerrado.':''].filter(Boolean).join('\\n');function button(label,fn){const b=document.createElement('button');b.type='button';b.className='text-xs px-3 py-2 rounded-xl border border-amber-400';b.textContent=label;b.onclick=fn;choices.append(b);}\n          if(!p.finished)for(const [id,a] of Object.entries(m.actions))button(a.label,()=>{try{draw(act(e,p,id));const topic=a.topic||m.cases.find(c=>c.id===p.id)?.topic;if(topic&&m.references?.[topic]){const ref=document.createElement('button');ref.textContent='Resumo clínico local';ref.onclick=()=>RFWorkspace.consultClinical(topic).catch(err=>{body.textContent+='\\n'+err.message;});choices.prepend(ref);const link=document.createElement('a');link.href=m.references[topic];link.target='_blank';link.rel='noopener noreferrer';link.textContent='Referência clínica';choices.prepend(link);}if(p.finished){e.npcs=e.npcs.filter(x=>x!==npc);e.scene.remove(npc.container);RF2.dispose(npc.container);if(e.rfScripts)e.rfScripts.entries=e.rfScripts.entries.filter(b=>b.ref!==npc);if(Object.values(s.ward).every(x=>x.finished)){if(m.completionFlag)e.storyFlags[m.completionFlag]=true;body.textContent+='\\nPlantão encerrado.\\n'+review(s.ward);}}}catch(err){draw(err.message);}});\n          GBM53.clinical(e,p,npc,message);gbLinkTerms(body,e,npc.name);button('Fluxograma',()=>GBFlow.open(e));button('PBL · hipóteses',()=>GBPBL.open(e,npc.name));button('Glossário',()=>GBPBL.glossary(e,npc.name));button('Revisão das condutas',()=>{body.textContent=review(s.ward);});button('Voltar ao cenário',()=>e.closeDialogue());}\n        draw();return true;}\n      return {sync,start,act,open,review};\n    })();\n"
FLOW_UI="      function open(e){const d=document.getElementById('gb-pbl'),m=e.mapData?.clinicalModule;if(!m)return;d.replaceChildren();const h=document.createElement('h3');h.textContent='Fluxogramas executados pelo módulo';const select=document.createElement('select'),a=document.createElement('textarea'),out=document.createElement('pre'),graph=document.createElement('div');graph.id='gbm53-graph';a.rows=14;out.style.whiteSpace='pre-wrap';const groups={...m.actions,behavior:m.behavior,triage:m.triage,guidance:m.guidance,exam:m.exam};for(const [id,g] of Object.entries(groups)){const o=document.createElement('option');o.value=id;o.textContent=g.label||id;select.append(o);}function refresh(){const g=groups[select.value];a.value=JSON.stringify(g.flow,null,2);GBM53.graph(g.flow,graph);out.textContent='Fluxo ativo. Alterações abaixo são prévias, não modificam o atendimento.';}select.onchange=refresh;a.oninput=()=>{try{const f=JSON.parse(a.value),r=analyze(f);out.textContent=r.errors.join('\\n')||'Prévia estrutural válida; não aplicada.';if(!r.errors.length)GBM53.graph(f,graph);}catch(err){out.textContent=err.message;}};const c=document.createElement('button');c.textContent='Fechar';c.onclick=()=>d.close();d.append(h,select,graph,a,out,c);refresh();if(!d.open)d.showModal();}\n"
CLINICAL_UI="      function feedback(p){return p.guidance;}\n      function clinical(e,p,npc,message){const body=document.getElementById('dialogue-text'),title=document.getElementById('dialogue-speaker'),f=p.module.facilitator;title.textContent=(p.module.profiles?.[npc.name]?.icon||'')+' '+npc.name+' · prontuário';if(p.observed.history)body.append(document.createTextNode('\\nExame físico simulado: '+p.exam));if(message&&f)body.append(document.createTextNode('\\n'+f.name+': '+feedback(p)));speak(message||(!p.observed.history?'Realize a avaliação clínica.':'Prontuário disponível para revisão.'),npc.name);if(message&&f){const b=document.createElement('button');b.textContent='Ouvir facilitador';b.onclick=()=>speak(feedback(p),f.name);document.getElementById('dialogue-choices').append(b);}}\n"
TEST="const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');\nconst s=fs.readFileSync('gamebras-base.html','utf8'),a=s.indexOf('const GBModuleRuntime='),b=s.indexOf('    const GBM4=',a);const C=vm.runInNewContext(s.slice(a,b)+'\\n({GBClinical,GBWard,GBModuleRuntime})',{structuredClone});\nconst m=JSON.parse(fs.readFileSync('modules/diabetes/aventura_diabetes.json','utf8')).clinicalModule;\nfunction p(id){return new C.GBClinical.Patient(id,m);}\ntest('empirical oral carbohydrate accepted, measurement improves score, recovery allows follow-up',()=>{const a=p('hypo'),b=p('hypo');a.act('carbs');assert.equal(a.score,1);a.advance(15);assert(a.state.g>=70);a.act('measure');a.act('plan');assert.equal(a.outcome,'appropriate');b.act('measure');b.advance(5);b.act('carbs');assert.equal(b.score,2);assert(b.log.at(-1).trace.length>1);});\ntest('referral and unsafe discharge differ; contraindicated oral route has no physiological effect',()=>{const a=p('dka'),b=p('dka');a.act('carbs');assert.equal(a.state.absorption,0);assert.equal(a.errors.length,1);a.act('refer');b.act('plan');assert.equal(a.outcome,'appropriate');assert.equal(b.outcome,'unsafe');});\ntest('measurement timestamp and patient isolation',()=>{const a=p('dm2'),b=p('hypo');a.act('measure');a.advance(10);assert.equal(a.observed.g.at,0);assert.equal(a.elapsed,10);assert.equal(b.elapsed,0);assert.equal(b.state.g,48);});\ntest('second non-diabetes module uses the same interpreter and ward',()=>{const second={schema:'gamebras.clinical/1',id:'demo',cases:[{id:'one',name:'Demo',story:'Synthetic test',state:{level:2}}],patients:{Test:'one'},evolution:{level:['add',['get','level'],1]},actions:{help:{minutes:1,label:'Help',rules:[{when:true,set:{level:8},message:'OK',points:1,classification:'appropriate'}],flow:{start:'c',nodes:[{id:'c',type:'condition',field:'match0',op:'eq',value:true,yes:'a',no:'z'},{id:'a',type:'action',action:'choose0',next:'z'},{id:'z',type:'end'}]}}}};C.GBClinical.use(second);const session={minute:0};C.GBWard.start(session,second);const p=session.ward.Test;p.advance(2);assert.equal(p.state.level,4);p.act('help');assert.equal(p.state.level,8);assert.equal(p.score,1);assert.equal(p.log[0].trace.join(','),'c,a,z');assert.throws(()=>p.act('carbs'));C.GBClinical.use(null);});\ntest('behavior, triage and guidance come from rules in the module',()=>{const a=p('hypo');assert.equal(a.behavior.level,'urgent');assert.equal(C.GBClinical.select(m.triage,a.context()).rule.value,'?');a.act('history');a.act('measure');assert.equal(C.GBClinical.select(m.triage,a.context()).rule.value,'R');a.act('carbs');a.advance(15);assert.equal(a.behavior.level,'stable');});\ntest('unknown operators and unauthorized state fields rejected',()=>{assert.throws(()=>C.GBClinical.expr(['eval','x'],{}));assert.throws(()=>C.GBClinical.expr(['get','constructor.prototype'],{}).x);const x=structuredClone(m);x.actions.measure.rules[0].set={undeclared:1};assert.throws(()=>new C.GBClinical.Patient('dm2',x).act('measure'));});\n"
SPEC='# Contrato clínico M6.4 — gamebras.clinical/1\n\nA campanha JSON contém `clinicalModule`. `cases` declara ID, narrativa, estado inicial; `patients` associa nomes dos NPCs aos casos; `actions` define duração, recurso opcional e grupos de regras. Cada grupo contém `rules` e `flow`: o executor M6.3 recebe os booleanos `matchN` calculados das condições, e as ações `chooseN` selecionam uma regra. A primeira condição verdadeira vence no fluxo padrão. Os efeitos só alteram campos de estado já declarados. `when`, `set`, `observe` e `message` aceitam literais ou arrays de expressão (`get`, `and`, `or`, `not`, `eq`, `ne`, `lt`, `lte`, `gte`, `add`, `sub`, `mul`, `min`, `max`, `round`, `concat`). Sem JavaScript de módulo. `evolution` contém expressões simultâneas por minuto; `behavior`, `triage`, `guidance`, `exam` são grupos de regras com `value`. `observations` define rótulos e unidades. `classification` distingue indicação e erro; `points` separa pontuação; `outcome` encerra atendimento. `profiles`, `facilitator`, `references`, `docs`, `glossary` e `completionFlag` são dados da campanha. A engine não contém critérios de diabetes.\n\nO JSON isolado desta pasta pode ser importado com os assets e documentos no mesmo ZIP. O bundle principal mantém as outras campanhas. Este snapshot é experimental, não instrumento de decisão clínica. O editor de fluxograma mostra o fluxo efetivamente usado, mas suas edições ainda são prévias. O modelo de fisiologia é simplificado, não validado clinicamente. A revisão dos sprites exclusivos e uma segunda campanha espacial completa permanecem pendentes. A geração de novos HTMLs no navegador ainda necessita selagem de identidade atualizada (M6.1 via ferramenta local); não confundir exportação com versão verificada. Use os testes e o manifesto para continuidade.\n'
def group(rules):
 nodes=[]
 for i,r in enumerate(rules):
  nodes.extend([dict(id=f'check{i}',type='condition',field=f'match{i}',op='eq',value=True,yes=f'pick{i}',no=f'check{i+1}' if i+1<len(rules) else 'end'),dict(id=f'pick{i}',type='action',action=f'choose{i}',next='end')])
 return dict(rules=rules,flow=dict(start='check0',nodes=nodes+[dict(id='end',type='end')]))
def G(k):return ['get',k]
def op(k,*v):return [k,*v]
def rule(when=True,**kw):return dict(when=when,**kw)
def module(s):
 import re,json,subprocess
 def literal(name):
  x=re.search(r'const '+name+r'=(.*?);\n',s,re.S).group(1)
  return json.loads(subprocess.check_output(['node','-e','process.stdout.write(JSON.stringify('+x+'))'],text=True))
 cases=literal('cases');actions=literal('actions');terms=literal('terms');profiles=literal('profiles');docs=literal('gbClinicalDocs');sample=literal('sample')
 dka=op('eq',G('kind'),'dka');hypo=op('eq',G('kind'),'hypo');dm2=op('eq',G('kind'),'dm2');low=op('lt',G('g'),70);severe=op('lt',G('g'),54);fresh=op('lte',op('sub',G('elapsed'),G('observed.g.at')),20);measured=op('and',op('ne',G('observed.g'),None),op('lt',G('observed.g.value'),70),fresh)
 goodplan=op('or',op('and',dm2,op('ne',G('observed.g'),None),op('ne',G('observed.history'),None)),op('and',hypo,op('gte',G('g'),70),op('gte',G('observed.g.value'),70),fresh))
 def R(message,when=True,points=0,classification='neutral',**kw):return rule(when,message=message,points=points,classification=classification,**kw)
 rules={
 'measure':[R('Glicemia registrada; reavalie após intervenções.',observe={'g':{'value':op('round',G('g')),'at':G('elapsed')}})],
 'ketones':[R('Cetonemia registrada.',observe={'k':{'value':G('k'),'at':G('elapsed')}})],
 'gas':[R('Gasometria venosa registrada.',observe={'gas':{'ph':G('ph'),'bicarbonate':G('bicarbonate'),'at':G('elapsed')}})],
 'history':[R(G('story'),observe={'history':{'text':G('story'),'at':G('elapsed')}})],
 'carbs':[R('Via oral inadequada neste cenário.',dka,-2,'error'),R('Carboidrato administrado; reavalie em 15 minutos.',op('and',low,measured),2,'appropriate',set={'absorption':op('add',G('absorption'),65)}),R('Tratamento empírico aceito; registre glicemia assim que possível e reavalie em 15 minutos.',low,1,'appropriate',set={'absorption':op('add',G('absorption'),65)}),R('Confirme recuperação antes de repetir carboidrato.',op('and',hypo,op('gte',G('absorption'),1))),R('Carboidrato sem indicação atual.',True,-2,'error')],
 'water':[R('Hidratação oral não substitui atendimento de urgência.',dka,-1,'error'),R('Hidratação oral registrada.',set={'water':op('max',0,op('sub',G('water'),.3))})],
 'insulin':[R('Intervenção sem avaliação de segurança: risco de hipoglicemia; na CAD é necessário protocolo monitorado.',True,-3,'error',set={'insulin':op('add',G('insulin'),30)})],
 'refer':[R('Transferência registrada. Não atrasar atendimento na suspeita de CAD.',dka,5,'appropriate',outcome='appropriate'),R('Transferência registrada por gravidade.',severe,3,'appropriate',outcome='appropriate'),R('Transferência registrada; revise necessidade conforme gravidade e resposta.',True,0,'neutral',outcome='referred')],
 'plan':[R('Plano compatível com o cenário; orientar retorno e seguimento.',goodplan,5,'appropriate',outcome='appropriate'),R('Alta insegura ou avaliação incompleta.',True,-5,'error',outcome='unsafe')],
 'wait':[R('Atraso em condição que exige intervenção.',op('or',dka,low),-2,'error'),R('O tempo passou; a condição pode evoluir.')]
 }
