def extract_bundle(s):
 m=BUNDLE.search(s)
 if not m:raise ValueError('Bundle ausente')
 if not m[2].strip():return None
 with zipfile.ZipFile(io.BytesIO(base64.b64decode(m[2]))) as z:return {i.filename:z.read(i) for i in z.infolist() if not i.is_dir()}
def migrate_bundle(s,m):
 files=extract_bundle(s)
 if files is None:return s,None
 roots=[]
 for n,b in files.items():
  if n.endswith('.json'):
   try:d=json.loads(b)
   except (UnicodeError,ValueError):continue
   if isinstance(d,dict) and isinstance(d.get('tiles'),list) and d.get('name')=='UBS — Plantão de diabetes':roots.append((n,d))
 if len(roots)!=1:raise ValueError('Campanha de diabetes não identificada de forma única')
 name,d=roots[0];d['clinicalModule']=copy.deepcopy(m)
 if 'npc_paulo' not in d['assets']:
  d['assets']['npc_paulo']=copy.deepcopy(d['assets']['hero_agente']);d['assets']['npc_paulo']['imageUrl']='./diabetes_paulo_sprite.png';files['diabetes_paulo_sprite.png']=files['diabetes_hero_sprite.png']
 for npc in d['npcs']:
  if npc['name']=='Paulo':npc['asset']='npc_paulo'
 for n,t in m['docs'].items():files.setdefault(n,t.encode())
 files[name]=json.dumps(d,ensure_ascii=False,indent=2).encode();out=io.BytesIO()
 with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
  for n,b in files.items():z.writestr(n,b)
 s=BUNDLE.sub(lambda x:x[1]+base64.b64encode(out.getvalue()).decode()+x[3],s,count=1)
 # Standalone clinical campaign, without the unrelated phases or editor libraries.
 standalone=copy.deepcopy(d);standalone.pop('phases',None)
 selected={name:json.dumps(standalone,ensure_ascii=False,indent=2).encode()}
 def walk(x):
  if isinstance(x,dict):
   for k,v in x.items():
    if k in {'imageUrl','url','src','spriteUrl','audioUrl','bgmUrl','nextJsonUrl','modelUrl'} and isinstance(v,str):
     n=v.removeprefix('./')
     if n in files:selected[n]=files[n]
    walk(v)
  elif isinstance(x,list):
   for v in x:walk(v)
 walk(standalone)
 for n,t in m['docs'].items():selected[n]=files[n]
 return s,selected

def js_checks(s):
 with tempfile.TemporaryDirectory() as t:
  p=P(t)/'check.js'
  for x in re.finditer(r'<script\b([^>]*)>(.*?)</script>',s,re.S|re.I):
   if 'type=' in x[1] or 'src=' in x[1]:continue
   p.write_text(x[2]);subprocess.run(['node','--check',str(p)],check=True)

